`timescale 1ns/1ps
module tb_mlkem_noise_sampler;reg clk=0,rst_n=0,start=0,ordy=1;reg[255:0]seed;reg[7:0]nonce;reg[1:0]eta;wire busy,done,error,ov;wire[11:0]oc;wire[7:0]oi;wire[1:0]dom;integer fd,rc,v,i,got,checks=0,cycles,totalcycles=0;reg[11:0]exp[0:255];string file;always#5 clk=~clk;mlkem_noise_sampler dut(clk,rst_n,start,seed,nonce,eta,busy,done,error,ov,ordy,oc,oi,dom);
 initial begin if(!$value$plusargs("VECTOR_FILE=%s",file))$fatal(1,"VECTOR_FILE");fd=$fopen(file,"r");repeat(3)@(negedge clk);rst_n=1;for(v=0;v<128;v=v+1)begin rc=$fscanf(fd,"%d %h %h\n",eta,nonce,seed);for(i=0;i<256;i=i+1)rc=$fscanf(fd,"%h\n",exp[i]);@(negedge clk);start=1;@(negedge clk);start=0;got=0;cycles=0;while(!done)begin @(negedge clk);cycles=cycles+1;if(cycles>2000)$fatal(1,"watchdog v=%0d",v);end totalcycles=totalcycles+cycles;if(error||got!=256)$fatal(1,"status v=%0d",v);end $display("PASS tb_mlkem_noise_sampler vectors=128 eta2=64 eta3=64 coeff_checks=%0d average_cycles=%0d",checks,totalcycles/128);$finish;end
 always@(posedge clk)if(ov&&ordy)begin if(oi!==got[7:0]||oc!==exp[got]||dom!=2'b01)$fatal(1,"v=%0d i=%0d exp=%0d got=%0d",v,got,exp[got],oc);got=got+1;checks=checks+1;end endmodule
